class BSTIterator {
    stack<TreeNode*> st;
    vector<int> history;
    int idx = -1;
    void pushLeft(TreeNode* node) {
        while (node) {
            st.push(node);
            node = node->left;
        }
    }
public:
    BSTIterator(TreeNode* root) {
        pushLeft(root);
    }

    bool hasNext() {
        return idx + 1 < (int)history.size() || !st.empty();
    }

    int next() {
        idx++;
        if (idx < (int)history.size()) return history[idx];
        TreeNode* node = st.top();
        st.pop();
        pushLeft(node->right);
        history.push_back(node->val);
        return node->val;
    }

    bool hasPrev() {
        return idx > 0;
    }

    int prev() {
        idx--;
        return history[idx];
    }
};

class BSTIterator {
    private Deque<TreeNode> stack = new ArrayDeque<>();
    private List<Integer> history = new ArrayList<>();
    private int idx = -1;
    private void pushLeft(TreeNode node) {
        while (node != null) {
            stack.push(node);
            node = node.left;
        }
    }
    public BSTIterator(TreeNode root) {
        pushLeft(root);
    }

    public boolean hasNext() {
        return idx + 1 < history.size() || !stack.isEmpty();
    }

    public int next() {
        idx++;
        if (idx < history.size()) return history.get(idx);
        TreeNode node = stack.pop();
        pushLeft(node.right);
        history.add(node.val);
        return node.val;
    }

    public boolean hasPrev() {
        return idx > 0;
    }

    public int prev() {
        idx--;
        return history.get(idx);
    }
}

